INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_saf_122', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-1-2' AND is_deleted = false LIMIT 1), 'measure-module-coupling', 'Measure coupling: fan-in, fan-out and instability', 'A one-line change to the shared utils module of the CodeDev API broke 9 features in one release, and nobody knew how many modules depended on it. Write analyzeCoupling(edges, limits) to turn the module dependency graph into numbers. Each edge is a string "a -> b" (module a imports module b); spaces around the arrow are optional. A line is valid when it contains exactly one "->" and each side, after trimming, is one non-empty module name without whitespace; count invalid lines in skipped and ignore them otherwise. The same edge listed twice counts once. A self-edge ("a -> a") adds no dependency, but every module named in a valid line appears in the report. fanIn = how many other modules import the module; fanOut = how many other modules it imports. instability = Math.round(fanOut * 100 / (fanIn + fanOut)) / 100, and 0 when fanIn + fanOut is 0. flags, in this order: "high-fan-in" when fanIn > limits.maxFanIn, "high-fan-out" when fanOut > limits.maxFanOut, otherwise an empty array. Sort the modules by fanIn (highest first), then fanOut (highest first), then name A to Z (compared with < and >). Return { modules: [{ module, fanIn, fanOut, instability, flags }], skipped }. The test runner reads { edges, limits } as JSON from stdin and prints the report as JSON. Up to a few thousand edges.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
