INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_saf_131', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-1-3' AND is_deleted = false LIMIT 1), 'dependency-direction-quiz', 'Which way does this import point?', 'Two pieces of evidence from the orders module: how OrderService gets its repository, and a layer check that found a domain file importing a service.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
