WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_131'), '// src/orders/services/orderService.ts
import { PostgresOrderRepository } from "../repositories/postgresOrderRepository";
import { db } from "../../shared/db";

export class OrderService {
  private orders = new PostgresOrderRepository(db);

  async placeOrder(userId: string, courseId: string) {
    // ... validate, charge, then:
    return this.orders.save({ userId, courseId, status: "paid" });
  }
}

$ npm test -- orderService
Error: connect ECONNREFUSED 127.0.0.1:5432

Statement: "orderService.ts calls a class method instead of writing SQL itself, so it does not depend on the database."', 'single_choice'::question_type, 'False. The service imports the concrete PostgresOrderRepository and the shared db connection, and creates the repository itself, so it depends on Postgres through that import: the unit test fails with ECONNREFUSED because placeOrder cannot run without a real database. Hiding the SQL in another class moves the code, not the dependency. The fix is to depend on an interface the service owns in the domain layer (an OrderRepository port with save()), receive an implementation in the constructor, and let only the composition root (main.ts) create PostgresOrderRepository. The misconception is that a dependency means "contains the SQL": a dependency is anything you import and cannot run without.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_131') AND order_index = 1)
    RETURNING id
)
