    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_131'), 'The layer check in CI, and the two files it points at:

$ npm run check:layers
src/orders/domain/order.ts -> src/orders/services/pricingService.ts  domain -> service  domain-must-be-pure
1 violation

// src/orders/domain/order.ts
import { applyDiscount } from "../services/pricingService";
export function orderTotal(order: Order): number {
  return applyDiscount(order.price, order.coupon);
}

// src/orders/services/pricingService.ts
import { orderTotal, type Order } from "../domain/order";
export function applyDiscount(price: number, coupon: string | null): number { /* pure arithmetic */ }
export function quote(order: Order) { return { total: orderTotal(order) }; }

Statement: "Moving applyDiscount into the domain (it is pure arithmetic and imports nothing) removes the violation and also the import cycle between order.ts and pricingService.ts."', 'single_choice'::question_type, 'True. Today order.ts imports pricingService.ts and pricingService.ts imports order.ts: a cycle, and the domain -> service arrow is the half that points the wrong way. applyDiscount uses nothing from the service layer, so it belongs next to orderTotal in the domain. After the move, the only arrow left is pricingService -> domain, which is allowed, and the check prints 0 violations. Verify it by rerunning the check and with a cycle finder such as madge --circular. The misconception is that a cycle must be broken with an interface or a third shared module; often one function is simply in the wrong layer.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_saf_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_saf_132', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-1-3' AND is_deleted = false LIMIT 1), 'check-dependency-direction', 'Check the dependency direction', 'Reviewers of the CodeDev API keep missing imports that point the wrong way between layers. Write the check that CI will run. layerOf(path): split the path on "/", drop the last part (the file name) and take the FIRST remaining folder named "controllers" (layer "controller"), "services" ("service"), "domain" ("domain") or "repositories" ("repository"), compared exactly (case-sensitive). A path with none of them has no layer (null) and is never checked, as importer or as import: shared code, packages such as "zod" or "node:crypto", tests. Allowed imports (importing layer -> imported layer): every layer may import its own layer and the domain; controller -> service is allowed. Forbidden, with the rule to report: controller -> repository is "controller-skips-service"; service -> repository is "service-needs-port" (a service reaches the database only through a port, an interface in the domain layer that a repository implements); service -> controller, repository -> controller and repository -> service are "points-backward"; domain -> controller, service or repository is "domain-must-be-pure". findViolations(files) gets [{ path, imports }] with imports already resolved to paths from the repository root, and returns one { file, import, from, to, rule } per forbidden import (from and to are the two layers). The same import listed twice in one file is reported once. Sort by file, then by import, both A to Z compared with < and >. No violations: an empty array. The test runner reads { files } as JSON from stdin and prints the result as JSON.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
