INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_132'), 1, 'Two separate questions decide each import: which layer is each path in, and is that pair of layers allowed? Can you answer the second one with a lookup instead of a chain of if statements?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_132'), 2, 'Look at layerOf first: the file name must not count (src/orders/services.ts has no layer), and the first matching folder wins (src/orders/domain/services/pricing.ts is domain). Then write the 4 x 4 table from the description as a nested object where an allowed cell is null and a forbidden cell holds the rule name, and remove repeated imports of one file before you check them.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_132'), 3, 'A similar check on another tree: the layers are "pages" -> "page" and "api" -> "api", and only api -> page is forbidden (rule "api-imports-ui"). For app/blog/pages/post.tsx, layerOf gives "page"; for app/blog/api/pages/list.ts it gives "api" (the first matching folder), and for app/blog/pages.ts it gives null. The file app/blog/api/pages/list.ts importing app/blog/pages/post.tsx twice gives one entry: { file: "app/blog/api/pages/list.ts", import: "app/blog/pages/post.tsx", from: "api", to: "page", rule: "api-imports-ui" }.');
