-- module 2: Ports & Refactoring
UPDATE course.module SET title = 'Ports & Refactoring', updated_at = now() WHERE id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1);
INSERT INTO course.module (course_id, title, order_index)
SELECT (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), 'Ports & Refactoring', 2
WHERE NOT EXISTS (SELECT 1 FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false);

-- lesson 2.1: Ports for payment and email: dependency inversion in practice (Sanity lesson-saf-2-1)
UPDATE course.lesson SET title = 'Ports for payment and email: dependency inversion in practice', order_index = 1, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-2-1' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), 'Ports for payment and email: dependency inversion in practice', 'sanity', 'lesson-saf-2-1', 1
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-saf-2-1' AND is_deleted = false);

