-- challenge chal_quiz_saf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_saf_221', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-2-2' AND is_deleted = false LIMIT 1), 'refactor-safely-quiz', 'Did the refactor keep the behaviour?', 'Two pieces of evidence from the calculatePrice cleanup: a green pull request whose test expectation changed in the same commit, and a golden-master check run after every small step.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221'), 'Pull request #812 "refactor(pricing): split calculatePrice, no behaviour change" - CI: 14 passed, 0 failed.

One of its commits:

--- a/pricing/calculatePrice.ts
+++ b/pricing/calculatePrice.ts
-  let total = (amount * 110) / 100;
-  total = Math.round(total);
+  const net = Math.round(amount);
+  return totalWithVat(net);

--- a/pricing/calculatePrice.test.ts
+++ b/pricing/calculatePrice.test.ts
   test("50% coupon on a 24,691 course", () => {
-    expect(calculatePrice(cart24691Half)).toBe(13580);
+    expect(calculatePrice(cart24691Half)).toBe(13581);
   });

Statement: "The 14 green tests show that this refactor kept the behaviour of calculatePrice."', 'single_choice'::question_type, 'False. A refactor changes structure, not results, so it should not need to change a single expected value. Here the same commit that moved the rounding before VAT also edited the test from 13580 to 13581: the test now checks the new behaviour, so its green result says nothing about the old one. The 1 đồng is a real change - invoices and the e-invoice totals would disagree. When a test fails during a refactor, the refactor is wrong (or the test was wrong, which is a separate, reviewed change), never something to update in passing. A quick review check: `git diff main -- ''*.test.ts''` on a refactor PR should show added tests, not edited expectations. The misconception is that green CI proves a refactor safe; it only proves the code agrees with the tests that are there now.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221'), 'Before touching calculatePrice, the team recorded 2,000 real carts from last month (staff carts, broken coupons and duplicate items included) and saved what the old function returned for each one in golden/prices.json. They then refactored in nine small commits (extract countedItems, extract bundlePercent, ...) and ran this after every commit:

$ npx vitest run pricing/golden.test.ts
  after commit 1-5:  2000/2000 identical
  after commit 6:    1993/2000 identical  (7 differ, e.g. cart #418: expected 338800, got 141900)

Commit 6 is "extract countedItems".

Statement: "Because the comparison ran after every small commit, the team knows the 7 differences come from extracting countedItems, which one comparison at the end of all nine commits could not have told them."', 'single_choice'::question_type, 'True. The golden master (also called a characterization test) records what the code does today, quirks included, and compares every later version against it. Run after each small step, a difference points at the one step that caused it: commit 6, which extracted countedItems - for example by removing duplicate course ids before dropping invalid prices instead of after, so a cart whose first copy of a course was invalid lost the course. Run only once at the end, the same 7 differences could come from any of nine commits, and you would be bisecting instead of fixing. The misconception is that small steps are about tidiness; they are what makes a failing comparison cheap to explain.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_saf_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_saf_222', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-2-2' AND is_deleted = false LIMIT 1), 'split-calculate-price', 'Split calculatePrice without changing a single price', 'calculatePrice(order) prices a cart of premium CodeDev courses. It is correct but written as one long function, and the starter gives it to you together with its spec: free for staff (only when order.staff is exactly true); an item counts only when its priceVnd is a positive whole number, and among those a repeated courseId counts once (the first one); no counted item or no items list means 0; the subtotal is the sum of counted prices; 3-4 counted courses give 10 percent off and 5 or more give 15 percent; a percent coupon { type: "percent", value } with a whole value from 1 to 100 gives value percent, and only the larger of the bundle and coupon percent applies (subtotal * (100 - p) / 100); then a fixed coupon { type: "fixed", value } with a positive whole value takes value đồng off, never below 0; any other coupon is ignored; finally 10 percent VAT and one rounding at the end, Math.round(net * 110 / 100). Write the small functions countedItems(items), subtotalOf(items), bundlePercent(count), couponPercent(coupon), fixedDiscount(coupon) and totalWithVat(net) with exactly these names and the signatures in the starter, then rewrite calculatePrice(order) on top of them. The test runner reads a list of calls ["functionName", argument] from stdin and prints "functionName -> <result as JSON>" for each, so every small function is tested on its own as well as calculatePrice. Hidden regression tests cover every rule and odd inputs (invalid prices, duplicates, bad coupons, half-đồng amounts, large carts): the results must be exactly those of the old code.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_222'), 1, 'Before you delete a line of the old function: which of its steps happen in a fixed order, and what would change in the result if two of them swapped places?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_222'), 2, 'Look closely at three spots in the old code: the order of the price check and the duplicate check in the item loop, how the bundle percent and the coupon percent are combined, and where Math.round is called. Run the old calculatePrice and your version on the same carts and compare.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_222'), 3, 'The same technique on a different function: an old `shippingFee(parcel)` that does `w = parcel.grams / 1000; if (w > 2) fee = 30000 + (w - 2) * 5000; else fee = 30000; return Math.round(fee * 1.08)` splits into `baseFee(kg)`, `overweightFee(kg)` and `withTax(fee)`, where only withTax rounds - rounding inside overweightFee would look harmless and change some totals by 1.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_222'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
