-- challenge chal_quiz_saf_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_saf_231', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-2-3' AND is_deleted = false LIMIT 1), 'circular-import-quiz', 'Is the import cycle gone?', 'Two pieces of evidence from the refund refactor: what tsc and madge say about the orders/payments cycle, and the assistant''s second attempt that loads orders inside refund().', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231'), '// orders/index.ts
import { charge, refundDeadline } from "../payments";
export const orderRepository = new OrderRepository(db);

// payments/index.ts (after the AI refactor)
import { orderRepository } from "../orders";
const refunds = new RefundService(orderRepository); // runs while payments loads
export function refund(orderId: string, today: string) { return refunds.refund(orderId, today); }

$ npx tsc --noEmit && echo "tsc ok"
tsc ok
$ npx madge --circular --extensions ts src/
✖ Found 1 circular dependency!
1) orders/index.ts > payments/index.ts

Production log: TypeError: Cannot read properties of undefined (reading ''getOrder'') at RefundService.refund

Statement: "tsc passes although RefundService received undefined at runtime: an import cycle has to be found by a separate check, such as madge --circular or the import/no-cycle lint rule."', 'single_choice'::question_type, 'True. TypeScript checks types, not load order: the type of orderRepository is OrderRepository, so new RefundService(orderRepository) type-checks. At runtime the server loads orders first; orders starts loading payments before its own orderRepository line has run, payments asks for orders, gets a module that is not finished yet, and RefundService keeps undefined. tsc has no rule for that, which is why teams add madge --circular, the import/no-cycle rule of eslint-plugin-import or a dependency-cruiser no-circular rule to CI. The misconception is that a clean tsc run means every import holds a value; types describe what a value should be, not whether the module that exports it has finished loading.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231'), 'The assistant''s second attempt, after the TypeError was reported:

// payments/index.ts
export function refund(orderId: string, today: string): RefundResult {
  const { orderRepository } = require("../orders"); // load orders when refund runs, not at startup
  return new RefundService(orderRepository).refund(orderId, today);
}

// orders/index.ts is unchanged and still imports charge and refundDeadline from ../payments

All refund tests pass now.

Statement: "This change removes the import cycle between orders and payments."', 'single_choice'::question_type, 'False. payments still needs orders and orders still needs payments; the require only moved from load time to call time. By the time refund runs, orders has finished loading, so the crash goes away - until someone uses orders at the top of payments again, or a test or a script loads payments first. The dependency still points the wrong way (payments, the lower-level module, knows about orders), and the two modules still cannot be built, tested or extracted separately. The fixes remove the edge: move what both need (the order records) into a third module, or give payments a small port it receives from outside, or keep refund orchestration in orders. The misconception is that a cycle is a load-time problem only; the crash was the symptom, the two-way dependency is the cause.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_saf_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_saf_232', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-circular-import', 'Spot the AI Mistake: a refactor with a circular import', 'An AI assistant was asked: "Move the refund logic out of the orders module into payments, where the rest of the money code lives. The order page must keep showing ''refundable until <date>''." It moved refund() into payments, and to find the order and mark it refunded, payments now loads orders - while orders already loads payments to charge and to show the deadline. Placing and showing orders still work, so the review passed. Since the release every refund fails with a TypeError, and support refunds learners by hand. The modules are objects registered with define() on a tiny module loader in the starter that behaves like CommonJS require(): a module that loads another module still in the middle of loading gets undefined, and every load() a module makes is recorded in an import graph. Fix the modules so that refunds work and the import graph has no cycle: payments.refund(orderId, today) keeps its signature and its rules (unknown_order, already_refunded, window_closed after paid-on date + 14 days, otherwise the order becomes refunded and the result carries a new refund id re_<n> and the amount), and orders keeps placeOrder, getOrder, markRefunded and describe. You may add modules with define() and the Modules interface. The test runner reads a list of actions (place, show, refund, graph) from stdin, loads orders and then payments like the app entry, and prints one line per action (only a summary line for more than 40 actions); the graph action prints "no import cycle" or the graph with the cycle it found. Do not change the loader, the shared types or the test runner. The public tests pass on the assistant''s code; the hidden tests refund orders and check the import graph.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
