INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_232'), 1, 'Run your code with the input [{"do":"graph"}]. Which module loads which, and when payments runs `load("orders")`, has orders finished loading yet?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_232'), 2, 'Look at what payments actually needs from orders: only getOrder and markRefunded, which work on the list of orders. Where could that list live so that both orders and payments can use it without either one loading the other?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_232'), 3, 'A similar cycle elsewhere: progress loads catalog to read lesson counts, and catalog loads progress to show "3 of 12 lessons done". Moving the lesson counts into a third module, lessons, that imports nothing, turns progress -> catalog -> progress into progress -> lessons and catalog -> lessons, catalog -> progress. Loading the other module inside a function instead of at the top would only hide the cycle.');
