VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_232'), 'Place two orders and show them with their refund deadline', '[{"do":"place","learnerId":"u_an","courseId":"nodejs-api-security","today":"2026-10-01"},{"do":"place","learnerId":"u_binh","courseId":"redis-patterns","today":"2026-10-20"},{"do":"show","orderId":"ord_1"},{"do":"show","orderId":"ord_2"},{"do":"show","orderId":"ord_7"}]', '"place u_an nodejs-api-security -> ord_1 (ch_1)\nplace u_binh redis-patterns -> ord_2 (ch_2)\nord_1: u_an nodejs-api-security 249000 paid on 2026-10-01, refundable until 2026-10-15\nord_2: u_binh redis-patterns 179000 paid on 2026-10-20, refundable until 2026-11-03\nord_7: not found"', 3, true, false, 1),
