INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_saf_311', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-3-1' AND is_deleted = false LIMIT 1), 'monolith-or-microservices-evidence', 'Monolith or Microservices? Read the evidence', 'RFC-031 proposes splitting the CodeDev platform into seven microservices, and its first step has already sent receipts for declined cards. Six statements on one evidence pack - the team map (A), the deploy pipeline (B), the traffic profile (C), the proposal (D) and the INC-77 trace (E) - take you from reading the evidence past two wrong explanations to a hypothesis, a decision and its verification.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
