    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_311'), 'Evidence A - team and ownership (CODEOWNERS, repository codedev-platform, one deployable app):
/src/modules/catalog/         @codedev/platform-team
/src/modules/orders/          @codedev/platform-team
