        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_311'), 'Evidence E - INC-77, two days after "extract notifications" was merged:
37 receipts sent for declined payments, 12 learners got course access without paying
Trace of one checkout (order o_51873)
10:14:02.104  orders         placeOrder o_51873 course=redis-patterns amount=149000
10:14:02.106  orders         email.sendReceipt -> POST notifications/receipts o_51873
10:14:02.131  notifications  receipt queued for hoa.tran@example.com o_51873
10:14:02.133  orders         events.publish order.paid o_51873
10:14:02.140  progress       grantAccess u_9310 redis-patterns (consumer of order.paid)
10:14:02.902  orders         payments.charge o_51873 -> declined (insufficient_funds)
10:14:02.910  orders         orders.save o_51873 payment_failed
PR #611, first hunk of placeOrder:
+    // notifications is its own service now: tell it as early as possible
+    deps.email.sendReceipt(order.learnerEmail, order.id, order.amountVnd);
+    deps.events.publish("order.paid", { orderId: order.id, learnerId: order.learnerId, courseId: order.courseId });
     const result = deps.payments.charge(order.id, order.amountVnd);

Statement: "A test that runs one successful checkout and asserts that exactly one receipt is sent proves that INC-77 is fixed."', 'single_choice'::question_type, 'False. The code from PR #611 also sends exactly one receipt for a successful checkout, so that test passes before and after the fix and cannot tell them apart. INC-77 is about declined payments: the test must run a declined checkout and a gateway timeout and assert that no receipt and no order.paid event are sent, and assert the call order for a paid order: charge, save as paid, receipt, event. In production, a query for receipts whose order is not paid should return the 37 rows before the deploy and none after it. The misconception is to test the happy path, which the incident never broke.', 6, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_311') AND order_index = 6)
    RETURNING id
)
