-- challenge chal_coding_saf_312 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_saf_312', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-3-1' AND is_deleted = false LIMIT 1), 'receipt-before-payment', 'Receipt Before Payment', 'Two days after the notifications module of CodeDev was extracted into its own service, learners report receipts for cards that were declined, and some of them can open courses they never paid for, because the progress module grants access when it sees an "order.paid" event. placeOrder(order, deps) uses four ports: PaymentGateway.charge, OrderRepository.save, EmailSender.sendReceipt and EventBus.publish. Fix it so that a valid order is charged first; when the charge succeeds, the order is saved as "paid" with its charge id and only then the receipt is sent and "order.paid" is published (result "paid"); a declined charge saves "payment_failed" and a gateway timeout saves "payment_unknown", and neither sends a receipt or publishes an event. Invalid orders (amount not a positive integer, email without "@") stay "rejected" with no port called. Input: a JSON list of checkouts { order, payment }, where payment ("succeeded", "declined" or "timeout") scripts the fake gateway. Output: for up to 10 checkouts the call log of the fakes and the result of each, then a summary line with the counts of results, receipts, events and side effects sent before the order was saved as paid; for more than 10 checkouts only the summary line.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
