INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_312'), 1, 'A receipt tells the learner "you paid" and order.paid tells progress "grant access". At the moment placeOrder sends them, what does it know about the payment?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_312'), 2, 'Run a declined checkout and read the call log from top to bottom: which lines appear before payments.charge? Then compare the three answers of the gateway: which of them make the order paid?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_saf_312'), 3, 'A similar case on other data: a password-reset flow that emails "your password was changed" and then calls users.updatePassword, which can fail validation. The safe order is update, check that it worked, save, and only then email; a failed update sends nothing.');
