WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-saf-3-2' AND is_deleted = false);

-- challenge chal_quiz_saf_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_saf_321', (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'software-architecture-fundamentals') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-saf-3-2' AND is_deleted = false LIMIT 1), 'shared-database-ownership', 'Shared databases: who owns the data?', 'Two statements on the orders table of CodeDev: a query from the progress module straight into a table owned by orders, and a versioned view that orders publishes for other modules.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321'), 'src/modules/progress/report.ts:
  SELECT o.id, o.course_id, o.amount, o.paid_at
    FROM orders o
   WHERE o.learner_id = $1 AND o.status = ''paid''

architecture/table-owners.json: "orders": ["orders"]
orders and progress are in the same repository, are deployed together by the same team
and connect to Postgres with the same database user.

Statement: "Because orders and progress are deployed together by one team, this query does not couple progress to the schema of the orders table."', 'single_choice'::question_type, 'False. The query depends on the table name, the column names (o.amount, o.paid_at) and on what status = ''paid'' means, all of which belong to the orders module. Deploying together only changes when the break shows up: a rename in orders still breaks progress, now at deploy time, as migration 0412 did when the health check failed with "column o.amount does not exist". Nothing in an import, a type or the orders tests reveals this dependency, which is why it is called hidden coupling. The misconception is that coupling only exists between separately deployed services; it exists wherever one module relies on another''s internals.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321'), 'migrations/orders/0410_paid_orders_view.sql (owned by the orders module):
  CREATE VIEW orders_api.paid_orders_v1 AS
  SELECT id AS order_id, learner_id, course_id, amount, paid_at
  FROM orders WHERE status = ''paid'';
  GRANT SELECT ON orders_api.paid_orders_v1 TO progress_app;   -- no grant on orders itself

src/modules/orders/paidOrdersView.test.ts asserts that the view returns the columns
order_id, learner_id, course_id, amount, paid_at.

Migration 0412 (orders module) renames orders.amount to orders.amount_vnd and, in the same file,
recreates the view with "amount_vnd AS amount". progress only reads orders_api.paid_orders_v1.

Statement: "With this setup, migration 0412 can rename the column without any change to the progress module."', 'single_choice'::question_type, 'True. Progress depends on the published contract (the view paid_orders_v1 and its five columns), not on the internal table. The orders module changes its table and its view in one migration, keeps the column amount in the view, and its own contract test proves the view still returns the same columns. The grant makes the rule enforceable: progress_app cannot select from orders directly, so it cannot grow a new hidden dependency. This is the acceptable kind of shared read: declared, versioned, owned and tested by the producer. The misconception is that any shared database access is equally bad; what matters is whether the owner controls and tests the contract.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_saf_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
